const pages=[["index.html","Обзор","home"],["landscape.html","Рынок","landscape"],["competitors.html","Конкуренты","competitors"],["audience.html","Аудитория","audience"],["opportunities.html","Возможности","opportunities"],["ecosystem.html","Экосистема","ecosystem"],["execution.html","Запуск","execution"],["final-report.html","Выводы","final"],["sources.html","Источники","sources"]];
const activePage=document.body.dataset.page||"home";
const headerHost=document.querySelector("[data-site-header]");
const footerHost=document.querySelector("[data-site-footer]");
if(headerHost){headerHost.innerHTML=`<header class="site-header"><div class="header-row"><a class="brand" href="index.html" aria-label="На главную"><span class="brand-mark">UA</span><span>COMMUNITY LAB<small>RESEARCH / 2026</small></span></a><button class="nav-toggle" type="button" aria-expanded="false" aria-controls="site-nav">Меню</button><nav class="site-nav" id="site-nav" aria-label="Основная навигация">${pages.map(([href,label,key])=>`<a href="${href}"${key===activePage?' aria-current="page"':""}>${label}</a>`).join("")}</nav><button class="summary-button" type="button" data-open-summary>Краткая выжимка</button></div></header>`}
if(footerHost){const currentIndex=pages.findIndex(([, ,key])=>key===activePage);const next=pages[(currentIndex+1)%pages.length];footerHost.innerHTML=`<footer class="site-footer"><div class="footer-row"><div><strong>Community Ecosystem Research</strong><p>Срез исследования: 28 октября 2026 · Украина и украинцы за рубежом</p></div><div class="footer-links"><a href="sources.html">Все 130 источников</a><a href="${next[0]}">Далее: ${next[1]} →</a></div></div></footer>`}
document.body.insertAdjacentHTML("beforeend",`<button class="summary-fab" type="button" data-open-summary aria-label="Открыть краткую выжимку">Выжимка ↗</button><dialog class="summary-dialog" id="summaryDialog" aria-labelledby="summaryTitle"><div class="dialog-head"><h2 id="summaryTitle">Краткая выжимка исследования</h2><button class="dialog-close" type="button" aria-label="Закрыть">×</button></div><div class="dialog-body"><div class="dialog-verdict">Возможность есть — но не для ещё одного универсального Discord. Продукт должен превращать незнакомцев в небольшие устойчивые группы через совместные действия и повторный контакт.</div><div class="dialog-grid"><article class="dialog-card"><b>Кому</b><p>Украинцы 20–35 внутри страны и за рубежом, у которых изменился привычный круг общения.</p></article><article class="dialog-card"><b>Обещание</b><p>Приходи один. Получи подходящую компанию. Сделайте что-то вместе и встретьтесь снова.</p></article><article class="dialog-card"><b>Продукт</b><p>Группы 4–6, host, activity-first знакомство, consent-first продолжение и сезоны 2–4 недели.</p></article><article class="dialog-card"><b>Платформы</b><p>TikTok — discovery, Telegram — медиа и реактивация, Discord — участие и отношения.</p></article><article class="dialog-card"><b>Рост</b><p>TikTok organic + микро-партнёрства + командные ритуалы. Referral — только после retention gate.</p></article><article class="dialog-card"><b>North star</b><p>Weekly Meaningful Repeat Connections: повторные взаимные контакты, а не участники или сообщения.</p></article><article class="dialog-card"><b>Монетизация</b><p>Supporter → sponsored seasons → платные дополнительные сезоны. Базовое общение остаётся бесплатным.</p></article><article class="dialog-card"><b>Главный риск</b><p>Массовый рост до появления плотности, host supply, safety и доказанного второго контакта.</p></article></div><a class="dialog-action" href="final-report.html">Открыть полный вывод →</a></div></dialog>`);
const dialog=document.getElementById("summaryDialog");document.querySelectorAll("[data-open-summary]").forEach(button=>button.addEventListener("click",()=>dialog.showModal()));document.querySelector(".dialog-close")?.addEventListener("click",()=>dialog.close());dialog?.addEventListener("click",event=>{const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close()});
if(new URLSearchParams(location.search).has("summary"))dialog?.showModal();
const toggle=document.querySelector(".nav-toggle"),nav=document.querySelector(".site-nav");toggle?.addEventListener("click",()=>{const open=nav.classList.toggle("open");toggle.setAttribute("aria-expanded",String(open))});
const search=document.getElementById("sourceSearch"),sourceItems=[...document.querySelectorAll(".source-item")],count=document.getElementById("sourceCount");if(search&&count){const filterSources=()=>{const query=search.value.trim().toLowerCase();let visible=0;sourceItems.forEach(item=>{const show=item.textContent.toLowerCase().includes(query);item.hidden=!show;if(show)visible++});count.textContent=`${visible} / ${sourceItems.length}`};search.addEventListener("input",filterSources);filterSources()}
